// Verify GitHub signature, keep only "issues/opened" for the configured repo.
// CONFIG lives here (n8n has no free secret store for Code nodes).
// Never commit this workflow with a real webhookSecret: the repo copy keeps the placeholder.
const crypto = require('crypto');

const CONFIG = {
  webhookSecret: 'REPLACE_WITH_WEBHOOK_SECRET',
  repo: 'easingthemes/dx-aem-flow',  // also hardcoded in the two GitHub tool URLs
  dailyRunCap: 20,                    // D009/D011: ~$0.05 worst case per run → ≤ $1/day
  perAuthorDailyCap: 3,
  maxIssueChars: 6000,
  maxCommentChars: 4000,
};

const item = $input.first();
const headers = item.json.headers || {};
const event = headers['x-github-event'];
const signature = String(headers['x-hub-signature-256'] || '');

let raw = null;
try { raw = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch (e) { raw = null; }
if (!raw) throw new Error('No raw body: enable "Raw Body" in the Webhook node options');
if (CONFIG.webhookSecret.startsWith('REPLACE_')) throw new Error('Set CONFIG.webhookSecret');

const expected = 'sha256=' + crypto.createHmac('sha256', CONFIG.webhookSecret).update(raw).digest('hex');
const valid = signature.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
if (!valid) throw new Error('Invalid webhook signature');

if (event === 'ping') return [];
const body = JSON.parse(raw.toString('utf8'));
if (event !== 'issues' || body.action !== 'opened') return [];
if (String(body.repository?.full_name || '').toLowerCase() !== CONFIG.repo.toLowerCase()) return [];

return [{ json: { config: CONFIG, issueNumber: body.issue.number } }];

// Guards from D009/D011 on data from the GitHub API: no PRs/bots, each issue once,
// max runs per day (cost proxy) and per author per day.
const cfg = $('Verify & filter').first().json.config;
const issue = $input.first().json;
const sd = $getWorkflowStaticData('global');

const today = new Date().toISOString().slice(0, 10);
if (sd.day !== today) { sd.day = today; sd.runs = 0; sd.authors = {}; }
sd.seen = sd.seen || [];

const login = String(issue.user?.login || '');
let reason = null;
if (issue.pull_request) reason = 'pull request';
else if (issue.state !== 'open') reason = 'issue not open';
else if (issue.user?.type === 'Bot' || login.endsWith('[bot]')) reason = 'bot author';
else if (sd.seen.includes(issue.number)) reason = 'already triaged';
else if ((sd.runs || 0) >= cfg.dailyRunCap) reason = 'daily run cap reached';
else if ((sd.authors[login] || 0) >= cfg.perAuthorDailyCap) reason = 'author daily cap reached';
if (reason) { sd.lastSkip = { issue: issue.number, reason, at: new Date().toISOString() }; return []; }

sd.runs = (sd.runs || 0) + 1;
sd.authors[login] = (sd.authors[login] || 0) + 1;
sd.seen = sd.seen.concat([issue.number]).slice(-500);

const clean = (s) => String(s || '').replace(/<\/?\s*issue[^>]*>/gi, '[tag removed]');
const body = String(issue.body || '');
return [{ json: {
  number: issue.number,
  title: clean(issue.title).slice(0, 300),
  body: clean(body).slice(0, cfg.maxIssueChars) + (body.length > cfg.maxIssueChars ? '\n[issue text truncated]' : ''),
} }];

// Sanitize the agent's answer before posting: no images, only github.com links, no @mentions.
const cfg = $('Verify & filter').first().json.config;
const issue = $('Guards').first().json;
let text = String($input.first().json.output || '').trim();
if (!text) return [];

text = text
  .slice(0, cfg.maxCommentChars)
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
  .replace(/https?:\/\/(?!github\.com\/)[^\s)>\]]+/gi, '[link removed]')
  .replace(/@(?=[A-Za-z0-9])/g, '@​');

const footer = '\n\n---\n<sub>Automated first triage by kai-hausmeister (AI agent). Not a maintainer decision.</sub>';
return [{ json: { number: issue.number, comment: text + footer } }];
